import type { Task } from "../../domain/task";

export interface AddTaskInput {
  projectId: string;
  title: string;
  description: string;
  dueDate?: string;
  status?: string;
}

export interface AssignTaskInput {
  taskId: string;
  assigneeId: string;
}

export interface ListProjectTasksInput {
  projectId: string;
  status?: string;
  assigneeId?: string;
}

export interface TaskDto {
  id: string;
  projectId: string;
  title: string;
  description: string;
  dueDate: string | null;
  status: string;
  assigneeId: string | null;
}

export function toTaskDto(task: Task): TaskDto {
  return {
    id: task.id,
    projectId: task.projectId,
    title: task.title,
    description: task.description,
    dueDate: task.dueDate === null ? null : task.dueDate.toISOString(),
    status: task.status,
    assigneeId: task.assigneeId,
  };
}

